# Helper: recursively extract a plain numeric value from possible wrappers
# ----------------------------------------------------------------------
def _extract_numeric(value):
    """Return the innermost numeric component from wrappers such as
    list/tuple, dict, or nested combinations. Returns None if no numeric
    value can be found."""
    # Unwrap list/tuple – take the first element (preserving order)
    if isinstance(value, (list, tuple)):
        if not value:
            return None
        return _extract_numeric(value[0])

    # Unwrap dict – prefer a 'value' key, otherwise search for any numeric
    if isinstance(value, dict):
        if "value" in value:
            return _extract_numeric(value["value"])
        for v in value.values():
            num = _extract_numeric(v)
            if isinstance(num, (int, float)):
                return num
        return None

    # Direct numeric value
    if isinstance(value, (int, float)):
        return value

    # Anything else is not numeric
    return None

